// TestJWTCrossCompatibility tests that JWT tokens generated by Go can be validated by Next.js and vice versa
// This is critical for gradual migration where both systems need to accept tokens from each other

func TestGoGeneratedTokenWithNextJS(t *testing.T) {
	if testing.Short() {
		t.Skip("Skipping integration test in short mode")
	}

	// Generate a token using Go backend
	registerBody := map[string]interface{}{
		"email":    fmt.Sprintf("jwt-test-%d@example.com", time.Now().Unix()),
		"password": "testpassword123",
		"name":     "JWT Test User",
	}

	resp, body := makeRequest(t, goAPIBaseURL+"/auth/register", "POST", registerBody)
	require.Equal(t, http.StatusCreated, resp.StatusCode)

	var result map[string]interface{}
	err := json.Unmarshal(body, &result)
	require.NoError(t, err)

	goToken, ok := result["accessToken"].(string)
	require.True(t, ok, "accessToken should be a string")
	require.NotEmpty(t, goToken)

	// Try to use the Go-generated token with Next.js API
	req, err := http.NewRequest("GET", nextJSAPIBaseURL+"/auth/me", nil)
	require.NoError(t, err)
	req.Header.Set("Authorization", "Bearer "+goToken)

	client := &http.Client{Timeout: 10 * time.Second}
	nextJSResp, err := client.Do(req)
	require.NoError(t, err)
	defer nextJSResp.Body.Close()

	// Next.js should accept the Go-generated token
	assert.Equal(t, http.StatusOK, nextJSResp.StatusCode,
		"Next.js should accept Go-generated JWT token")
}

